    "Open the coin on ArcPad →": "ArcPad에서 코인 열기 →",
    "Couldn't read locks right now.": "지금은 잠금 정보를 읽을 수 없습니다.",
    "Connect a wallet to see and manage your locks.": "지갑을 연결하면 내 잠금을 보고 관리할 수 있습니다.",
    "Loading your locks…": "내 잠금을 불러오는 중…",
