    "Not live": "미출시",
    "$ARCIRCLE is relaunching": "$ARCIRCLE 재런칭 준비 중",
    "The core coin of ARCIRCLE PAD is getting a fresh launch. Until it goes live there is no official contract, price or chart — the new contract address will be posted here and on": "ARCIRCLE PAD의 코어 코인이 새로 런칭됩니다. 출시 전까지는 공식 컨트랙트, 가격, 차트가 없으며 — 새 컨트랙트 주소는 출시되는 순간 여기와 다음 계정에 게시됩니다:",
    "the moment it launches.": "(출시 즉시)",
    "Only trust the contract address published on arcircle.app or by": "arcircle.app 또는 다음 계정이 공개한 컨트랙트 주소만 믿으세요:",
    "Get the launch alert": "출시 알림 받기",
    "Get the launch alert ↗": "출시 알림 받기 ↗",
    "About $ARCIRCLE": "$ARCIRCLE 소개",
    "Relaunching soon — the new contract will be announced here": "곧 재런칭 — 새 컨트랙트는 여기서 공지됩니다",
    "Details →": "자세히 →",
    "Relaunching soon — CirclePad's share of every raise will feed it": "곧 재런칭 — CirclePad 모금액의 일부가 여기로 흘러갑니다",
    "$ARCIRCLE · Not live": "$ARCIRCLE · 미출시",
