    "Funding": "재원",
    "My wallet": "내 지갑",
    "Utility · Circle CCTP": "유틸리티 · Circle CCTP",
    "Move USDC between Arc and other chains. It's Circle's own Cross-Chain Transfer Protocol: native USDC is burned on one side and minted on the other — no wrapped tokens, no pools, and Circle delivers it on the other side so you don't need gas there.": "Arc와 다른 체인 사이에서 USDC를 옮기세요. Circle의 공식 크로스체인 전송 프로토콜(CCTP)을 씁니다. 한쪽에서 네이티브 USDC를 소각하고 다른 쪽에서 발행하므로 래핑 토큰도, 풀도 없으며, 도착 체인에서는 Circle이 대신 전달해 줘서 그쪽 가스가 필요 없습니다.",
    "From": "보내는 곳",
    "To": "받는 곳",
    "You receive at least": "최소 수령액",
    "Fast": "빠름",
    "Standard": "표준",
    "About a minute": "약 1분",
    "no transfer fee": "전송 수수료 없음",
    "15–20 min": "15–20분",
    "6–32 h": "6–32시간",
    "about 8 min": "약 8분",
    "under a minute": "1분 이내",
