    "Transfer fee": "전송 수수료",
    "Delivery on": "전달 비용 ·",
    "Most you'll pay": "최대 비용",
    "Enter an amount": "금액을 입력하세요",
    "Switch network": "네트워크 전환",
    "Approve USDC": "USDC 승인",
    "Your USDC goes straight to Circle's CCTP contracts — ARCIRCLE PAD never holds it and takes no fee. Fees are Circle's, deducted from the amount you send; you only pay gas on the chain you send from.": "USDC는 Circle의 CCTP 컨트랙트로 바로 갑니다. ARCIRCLE PAD는 자금을 보관하지 않으며 수수료도 받지 않습니다. 수수료는 Circle의 것으로 보내는 금액에서 차감되고, 가스는 보내는 체인에서만 냅니다.",
    "Attest": "서명",
    "Mint": "발행",
    "Your USDC is burned by Circle's contract on the chain you send from.": "보내는 체인에서 Circle 컨트랙트가 USDC를 소각합니다.",
    "Circle signs that the burn happened — seconds with Fast, after finality with Standard.": "Circle이 소각을 확인해 서명합니다. 빠름은 몇 초, 표준은 최종 확정 후입니다.",
    "The same amount of native USDC is minted to you on the other chain, delivered by Circle.": "같은 금액의 네이티브 USDC가 반대편 체인에서 발행되어 Circle이 전달합니다.",
    "Your transfers": "내 전송 내역",
    "Saved in this browser": "이 브라우저에 저장",
    "No transfers yet.": "아직 전송 내역이 없습니다.",
    "Free": "무료",
    "Unavailable": "확인 불가",
    "You claim it yourself": "직접 수령",
    "Enter a valid recipient": "올바른 받는 주소를 입력하세요",
    "Fee quote unavailable — try again": "수수료 조회 실패 — 다시 시도",
    "Getting a quote…": "견적 확인 중…",
    "The amount doesn't cover Circle's fees.": "금액이 Circle 수수료보다 적습니다.",
    "Approve USDC in your wallet…": "지갑에서 USDC 사용을 승인하세요…",
    "Confirm the transfer in your wallet…": "지갑에서 전송을 확인하세요…",
    "Sent — burning on": "전송됨 — 소각 중:",
    "The burn transaction failed — your USDC didn't move.": "소각 거래가 실패했습니다. USDC는 움직이지 않았습니다.",
    "Burned. Circle is on it — follow it under Your transfers.": "소각 완료. Circle이 처리 중입니다 — 내 전송 내역에서 확인하세요.",
    "You cancelled in your wallet.": "지갑에서 취소했습니다.",
    "Not enough gas on this chain for the transaction.": "이 체인에 거래할 가스가 부족합니다.",
    "Something went wrong.": "문제가 발생했습니다.",
