    "Selling works": "매도 가능",
    "Buying works": "매수 가능",
    "Sending works": "전송 가능",
    "ArcPad's 1% pool fee, taken on every buy and sell.": "ArcPad 풀 수수료 1%, 모든 매수·매도에 적용.",
    "A standard token answers name, symbol, decimals and supply the same way wallets and exchanges expect.": "표준 토큰은 지갑과 거래소가 기대하는 방식으로 이름, 심볼, 소수점, 공급량에 답합니다.",
    "A proxy keeps its logic in another contract that can be swapped. Whoever controls the proxy can change how the token behaves.": "프록시는 로직을 교체 가능한 다른 컨트랙트에 둡니다. 프록시를 쥔 사람이 토큰 동작을 바꿀 수 있습니다.",
    "Tokens from a known launchpad follow a fixed template, so there is less room for hidden tricks.": "알려진 런치패드의 토큰은 정해진 템플릿을 따라 숨은 장치가 들어갈 여지가 적습니다.",
    "The owner can call owner-only functions. Renounced ownership means nobody can any more.": "소유자는 소유자 전용 함수를 호출할 수 있습니다. 소유권을 포기하면 이제 아무도 못 합니다.",
    "With role-based permissions several wallets can hold admin rights, even without an owner.": "역할 기반 권한이면 소유자가 없어도 여러 지갑이 관리자 권한을 가질 수 있습니다.",
    "Found by reading the function list in the contract's code. It shows what the code allows, not whether it has been used.": "컨트랙트 코드의 함수 목록을 읽어 찾았습니다. 코드가 허용하는 것이지, 실제로 쓰였는지는 아닙니다.",
    "The scanner pretends to be a real holder and sends a little in a dry run — nothing is signed or spent — to see whether it arrives and how much is taken.": "스캐너가 실제 보유자인 것처럼 소량을 모의로 보내봅니다 — 서명도 지출도 없이 — 도착하는지, 얼마나 떼이는지 확인합니다.",
    "Taxes or fees charged on every trade go to the creator or the platform.": "매 거래마다 붙는 세금이나 수수료는 생성자나 플랫폼으로 갑니다.",
    "Without a pool with enough money in it you may not be able to sell at a fair price.": "충분한 돈이 들어 있는 풀이 없으면 제값에 팔지 못할 수 있습니다.",
    "Liquidity is how much money sits in the pool. Thin pools move a lot on small trades.": "유동성은 풀에 들어 있는 돈의 양입니다. 얕은 풀은 작은 거래에도 크게 움직입니다.",
    "New pools have little history, which is when most rug pulls happen.": "새 풀은 기록이 적고, 러그풀은 대부분 이때 일어납니다.",
    "A token that is bought a lot but never sold is a classic sign that selling is blocked.": "많이 사는데 아무도 팔지 않는 토큰은 매도가 막혀 있다는 전형적인 신호입니다.",
    "Legit projects usually list a website and social accounts on Dexscreener.": "정상적인 프로젝트는 보통 Dexscreener에 웹사이트와 소셜 계정을 등록합니다.",
    "How many wallets hold the token, and whether a few of them could dump on everyone else.": "몇 개의 지갑이 보유하고 있는지, 소수가 나머지 모두에게 물량을 던질 수 있는지.",
    "New tokens minted after launch dilute every holder.": "런치 후 발행된 새 토큰은 모든 보유자를 희석시킵니다.",
    "Events read from the token's own on-chain history.": "토큰 자체의 온체인 기록에서 읽은 이벤트입니다.",
