    "Token locks": "토큰 잠금",
    "Uses Uniswap's own PositionManager on Arc. Amounts can move up to 1% if the price shifts before your transaction lands.": "Arc의 Uniswap 공식 PositionManager를 사용해요. 트랜잭션이 처리되기 전에 가격이 움직이면 수량이 최대 1%까지 달라질 수 있어요.",
