    "Lock withdrawn": "잠금 해제 출금",
    "No liquidity was added or removed in the last 24 hours.": "최근 24시간 동안 유동성 추가·제거가 없었습니다.",
    "Liquidity was pulled": "유동성이 빠졌습니다",
    "of a pool's liquidity was removed in the last 24 hours.": "의 풀 유동성이 최근 24시간 동안 제거되었습니다.",
    "See activity": "활동 보기",
    "Your liquidity": "내 유동성",
    "Finding your positions on Arc…": "Arc에서 내 포지션을 찾는 중…",
    "No liquidity positions in this wallet yet.": "이 지갑에는 아직 유동성 포지션이 없습니다.",
    "Couldn't list your positions right now.": "지금은 포지션 목록을 불러오지 못했습니다.",
    "pool": "풀",
    "One project at a time. A 3-day USDC raise decides who leads it — and $ARCIRCLE holders vote on what it becomes, burning 1,000 $ARCIRCLE per vote.": "한 번에 하나의 프로젝트. 3일간의 USDC 모금으로 리드를 정하고, 무엇이 될지는 $ARCIRCLE 보유자가 1표당 $ARCIRCLE 1,000개를 소각하며 투표로 정합니다.",
    "Name, ticker, logo and roadmap are all decided by $ARCIRCLE holders' votes once a raise closes — every vote burns 1,000 $ARCIRCLE. This card shows the shape of a round — it isn't a real one yet.": "모금이 끝나면 이름, 티커, 로고, 로드맵을 모두 $ARCIRCLE 보유자의 투표로 정합니다 — 1표마다 $ARCIRCLE 1,000개가 소각됩니다. 이 카드는 라운드의 형태를 보여줄 뿐, 실제 라운드는 아닙니다.",
    "Anyone holding $ARCIRCLE can vote — 1 vote = 1,000 $ARCIRCLE, burned.": "$ARCIRCLE 보유자라면 누구나 투표할 수 있어요 — 1표 = $ARCIRCLE 1,000개 소각.",
    "$ARCIRCLE holders vote on name, ticker, logo, roadmap, date — every vote burns 1,000 $ARCIRCLE.": "$ARCIRCLE 보유자가 이름, 티커, 로고, 로드맵, 날짜에 투표합니다 — 1표마다 $ARCIRCLE 1,000개 소각.",
    "Anyone holding $ARCIRCLE can vote on the project's identity. Every vote costs 1,000 $ARCIRCLE, sent to the dead address (0x…dEaD) — burned for good, so every vote shrinks the supply. Vote as many times as you like; votes can't be changed or taken back. Five things get decided this way:": "$ARCIRCLE 보유자라면 누구나 프로젝트의 정체성에 투표할 수 있습니다. 1표에 $ARCIRCLE 1,000개가 들고, 이 토큰은 소각 주소(0x…dEaD)로 보내져 영구히 사라집니다 — 투표할수록 공급량이 줄어듭니다. 원하는 만큼 투표할 수 있고, 투표는 바꾸거나 되돌릴 수 없습니다. 이렇게 다섯 가지를 정합니다:",
    "One project. A 3-day USDC raise decides who leads it and how it's split. $ARCIRCLE holders vote on what it becomes.": "하나의 프로젝트. 3일간의 USDC 모금으로 리드와 분배를 정합니다. 무엇이 될지는 $ARCIRCLE 보유자가 투표로 정합니다.",
    "A single project raises USDC for 3 days on Arc. Every bid is recorded with the bidder's address and amount — this is what determines the final payout split.": "하나의 프로젝트가 Arc에서 3일간 USDC를 모금합니다. 모든 입찰은 입찰자 주소와 금액으로 기록되며, 이것으로 최종 지급 분배가 정해집니다.",
    "Whoever bid the most becomes the project lead. The project's actual identity — coin name, ticker, logo, roadmap and launch date — is voted on by $ARCIRCLE holders: every vote burns 1,000 $ARCIRCLE.": "가장 많이 입찰한 사람이 프로젝트 리드가 됩니다. 프로젝트의 실제 정체성 — 코인 이름, 티커, 로고, 로드맵, 런치 날짜 — 는 $ARCIRCLE 보유자가 투표로 정하며, 1표마다 $ARCIRCLE 1,000개가 소각됩니다.",
    "Yes — if the lead is ever marked abandoned, unvested funds return to all original bidders proportionally, not just the lead.": "네 — 리드가 이탈로 표시되면 아직 베스팅되지 않은 자금은 리드만이 아니라 모든 원래 입찰자에게 비율대로 돌아갑니다.",
    "Candidates go up during the raise. Voting opens the moment it closes and runs for 48 hours: 1 vote = 1,000 $ARCIRCLE, burned for good.": "후보는 모금 중에 올라옵니다. 투표는 모금이 끝나는 순간 열려 48시간 동안 진행됩니다: 1표 = $ARCIRCLE 1,000개, 영구 소각.",
    "Voting is open. Anyone holding $ARCIRCLE can vote — every vote burns 1,000 $ARCIRCLE.": "투표가 열렸어요. $ARCIRCLE 보유자라면 누구나 투표할 수 있고, 1표마다 $ARCIRCLE 1,000개가 소각돼요.",
    "Voting opens as soon as the burn-vote contract is live.": "소각 투표 컨트랙트가 배포되는 대로 투표가 열려요.",
    "Candidates are up — voting opens at the close. 1 vote = 1,000 $ARCIRCLE burned.": "후보가 올라왔어요 — 모금 마감과 함께 투표가 열려요. 1표 = $ARCIRCLE 1,000개 소각.",
    "Connect a wallet holding $ARCIRCLE to vote — 1 vote burns 1,000 $ARCIRCLE.": "$ARCIRCLE이 있는 지갑을 연결해 투표하세요 — 1표에 $ARCIRCLE 1,000개가 소각돼요.",
    "Hold $ARCIRCLE to vote: every 1,000 is one vote, burned when you cast it.": "$ARCIRCLE을 보유하면 투표할 수 있어요: 1,000개가 1표이고, 투표할 때 소각돼요.",
    "Each vote burns 1,000 $ARCIRCLE — it can't be changed or taken back.": "1표마다 $ARCIRCLE 1,000개가 소각돼요 — 바꾸거나 되돌릴 수 없어요.",
    "You need at least 1,000 $ARCIRCLE for one vote.": "1표에는 $ARCIRCLE이 최소 1,000개 필요해요.",
    "votes cast": "표 투표함",
    "burned": "소각",
