    "Replay the reveal": "결과 공개 다시 보기",
    "Round #1 · burn-to-vote is open": "라운드 #1 · 소각 투표 진행 중",
    "Round #1 · the vote is in": "라운드 #1 · 투표 결과",
    "Round #1 — what's fixed, what's planned, what isn't decided": "라운드 #1 — 확정된 것, 계획된 것, 미정인 것",
    "See the result": "결과 보기",
    "Split at the close": "마감 시 분배",
