    "You hold enough $ARCIRCLE for the next Relay Launch.": "다음 릴레이 런치에 필요한 $ARCIRCLE을 충분히 보유하고 있어요.",
    "You need {n} more $ARCIRCLE for the next Relay Launch (locked tokens count).": "다음 릴레이 런치까지 $ARCIRCLE {n}개가 더 필요해요 (락한 토큰도 인정).",
