    "Practice finds aren't paid. Pick a live mine to mine for real.": "연습 채굴은 보상이 없습니다. 실제로 캐려면 진행 중인 광산을 고르세요.",
    "Practice mine": "연습 광산",
    "Put part of your token's supply in the ground": "토큰 공급량 일부를 땅에 묻으세요",
    "Put part of your token's supply in the ground. Builders dig it over the days you pick; what nobody digs is burned. You can't take it back.": "토큰 공급량의 일부를 땅에 묻으세요. 빌더들이 정한 기간 동안 캐고, 아무도 캐지 않은 물량은 소각됩니다. 되돌려받을 수 없습니다.",
    "Rare finds": "희귀 광석",
    "Referrals": "추천",
    "Roots are posted every hour and can only grow.": "루트는 매시간 올라가고 줄어들 수 없습니다.",
    "Runs for": "진행 기간",
    "Same game — try your pickaxe": "같은 게임 — 곡괭이를 휘둘러 보세요",
    "Settled every hour — the first results appear after the first hour.": "매시간 정산됩니다. 첫 결과는 첫 한 시간이 지난 뒤 나옵니다.",
    "Sign once to start mining — it's only a signature.": "채굴을 시작하려면 한 번 서명하세요. 서명만 할 뿐입니다.",
    "Six layers, each half as rich": "여섯 층, 층마다 절반씩",
    "Start mining": "채굴 시작",
    "Stone": "암반층",
    "Stone pickaxe": "돌 곡괭이",
    "That isn't an ERC-20 token on Arc.": "Arc의 ERC-20 토큰이 아닙니다.",
    "The Builder Mine contract isn't live on Arc yet. Mine here for fun — the game is the same, but nothing is sent, paid or claimed.": "빌더 마인 컨트랙트가 아직 Arc에 배포되지 않았습니다. 여기서 재미로 캐 보세요. 게임은 같지만, 아무것도 보내거나 지급하거나 청구하지 않습니다.",
    "The Builder Mine contract isn't live yet.": "빌더 마인 컨트랙트가 아직 배포되지 않았습니다.",
    "The leaderboard fills as builders mine.": "빌더들이 캘수록 리더보드가 채워집니다.",
    "The mine's tokens sit in the contract. Nobody — not the creator, not ARCIRCLE PAD — can take them back.": "광산의 토큰은 컨트랙트에 있습니다. 개설자도 ARCIRCLE PAD도 가져갈 수 없습니다.",
    "The mine, drawn live": "실시간으로 그려지는 광산",
    "The rest arrives with the next hourly root.": "나머지는 다음 시간 루트와 함께 들어옵니다.",
    "Then anything unclaimed is burned. Nothing ever goes back to the mine's creator.": "그 뒤 청구되지 않은 물량은 소각됩니다. 광산 개설자에게는 아무것도 돌아가지 않습니다.",
    "They get +5% too.": "그들도 +5%를 받습니다.",
    "This browser can't run the miner (Web Workers are off).": "이 브라우저에서는 채굴기를 실행할 수 없습니다 (Web Worker 꺼짐).",
