    "A 7-day streak": "7일 연속 채굴",
    "A mine runs 3–60 days in six equal layers. The first layer releases half of everything, so the earliest builders dig the richest ground. A top-up is released over what's left of the curve.": "광산은 3–60일 동안 여섯 층으로 진행됩니다. 첫 층에서 전체의 절반이 풀려 가장 먼저 온 빌더가 가장 풍부한 땅을 캡니다. 추가 예치분은 남은 곡선을 따라 풀립니다.",
    "A pickaxe is yours for good and works in every mine. An upgrade costs only the difference. Every $ARCIRCLE you pay is burned. Better pickaxes leave a trail when they strike.": "곡괭이는 영구히 내 것이고 모든 광산에서 쓸 수 있습니다. 업그레이드는 차액만 냅니다. 지불한 $ARCIRCLE은 전부 소각됩니다. 좋은 곡괭이일수록 내리칠 때 잔상이 남아요.",
    "All three today": "오늘 세 개 모두",
    "Amethyst pickaxe": "자수정 곡괭이",
    "Any moment…": "곧 나와요…",
    "Anyone can add more to a running mine. It's released over what's left of the curve — none of it counts as already mined — and, like the deposit, it can never come back.": "진행 중인 광산에는 누구나 더 넣을 수 있습니다. 추가분은 남은 곡선을 따라 풀리고(이미 채굴된 것으로 치지 않음), 예치금처럼 되돌려받을 수 없습니다.",
    "Back to the mine": "광산으로",
    "Badges": "배지",
    "Boosts belong to one mine and run for a set time — you'll see them in the mine. Buy them after you join. The $ARCIRCLE is burned.": "부스트는 한 광산에서 정해진 시간 동안 작동하고, 광산 화면에 보입니다. 참여한 뒤에 사세요. $ARCIRCLE은 소각됩니다.",
