    "Dig 100 shares": "셰어 100개 캐기",
    "Digging now": "지금 채굴 중",
    "Each hour the mine pays out by points × pickaxe × bonuses. In a live mine: join, post once on X, then claim. Pick your builder and pet below.": "매시간 포인트 × 곡괭이 × 보너스로 나눠 지급됩니다. 실제 광산에서는 참여하고, X에 한 번 올리고, 청구하세요. 아래에서 빌더와 펫을 골라 보세요.",
    "Each hour's release is split by weight. Your browser does the hashing only while you press Start and the tab is open, and hands in its shares every 30 seconds.": "매시간 풀리는 물량을 가중치대로 나눕니다. 해시 계산은 시작을 누르고 탭을 열어 둔 동안에만 하고, 셰어는 30초마다 제출합니다.",
    "Edit the mine": "광산 정보 수정",
    "Enter the mine": "광산 입장",
    "Every swing that lands is a share, +1 point. Rare ores add more: copper to the Arc Crystal jackpot. The bar at the top shows when the next one is due.": "명중한 한 번 한 번이 셰어(+1 포인트)입니다. 희귀 광석은 더 줍니다: 구리부터 아크 크리스탈 잭팟까지. 위쪽 막대가 다음 셰어까지 남은 정도를 보여줘요.",
    "Everyone who has found the Arc Crystal — 1 in 16,384 shares — stays here for good.": "셰어 16,384개 중 하나인 아크 크리스탈을 캔 사람은 모두 여기에 영원히 남습니다.",
