    "The busiest mines are shown — switch to Cards for all of them.": "가장 붐비는 광산만 보여요 — 전부 보려면 카드로 바꾸세요.",
    "The dashboard works once the mine is live.": "광산이 열리면 대시보드가 작동해요.",
    "The fee to join or open: 1 USDC worth, burned.": "참여·개설 수수료: 1 USDC 상당, 소각돼요.",
    "The first hour hasn't settled yet.": "첫 1시간이 아직 정산되지 않았어요.",
    "This hour's rush ore: its points ×3": "이번 시간의 러시 광석: 포인트 ×3",
    "This is the practice mine: the same game, but nothing is paid. Pick a live mine to mine for real.": "연습 광산이에요: 게임은 같지만 보상은 없어요. 실제로 채굴하려면 진행 중인 광산을 고르세요.",
    "This mine, hour by hour": "이 광산의 시간별 기록",
