    "Proxy that can't be repointed": "바꿀 수 없는 프록시",
    "Published (verified) source code lets anyone read what the contract does. Unpublished code can hide tricks the scanner can't see.": "공개(검증)된 소스 코드는 누구나 컨트랙트가 하는 일을 읽을 수 있게 합니다. 공개되지 않은 코드는 스캐너가 볼 수 없는 수법을 숨길 수 있습니다.",
    "Reading the wallet's history…": "지갑 기록을 읽는 중…",
