    "new Argus launches": "신규 Argus 런칭",
    "of new profit above the desk's previous high buys $ARCIRCLE and sends it to 0x…dEaD, through the desk contract.": "의 신규 수익(이전 최고점 초과분)으로 $ARCIRCLE을 사서 데스크 컨트랙트를 통해 0x…dEaD로 보냅니다.",
